//! Permeability derived from material composition and exact physical interface.
use crate::resources::{BaseResource,Material};
pub fn water_mass_fraction(material:&Material,catalog:&[BaseResource])->f64{if !material.is_valid(){return 0.0}let mut total=0.0;let mut water=0.0;if let Some(s)=material.structure(){for c in &s.constituents{let Some(r)=catalog.iter().find(|r|r.name==c.resource)else{return 0.0};let m=r.properties.mass;total+=m;if c.resource=="Water"{water+=m}}}else{for c in material.composition(){let Some(r)=catalog.iter().find(|r|r.name==c.resource)else{return 0.0};let m=r.properties.mass*c.amount;total+=m;if c.resource=="Water"{water+=m}}}if total<=0.0||!total.is_finite()||!water.is_finite(){0.0}else{(water/total).clamp(0.0,1.0)}}
pub fn permeability(material:&Material,catalog:&[BaseResource],interface_length:f64,participating_boundary_length:f64)->Option<f64>{if !material.is_valid()||!interface_length.is_finite()||!participating_boundary_length.is_finite()||interface_length<0.0||participating_boundary_length<0.0{return None}if participating_boundary_length==0.0{return Some(0.0)}let result=water_mass_fraction(material,catalog)*(interface_length/participating_boundary_length).clamp(0.0,1.0);result.is_finite().then_some(result.clamp(0.0,1.0))}
#[cfg(test)]mod tests{use super::*;use crate::resources::default_catalog;#[test]fn pure_water_has_full_water_mass_fraction(){let c=default_catalog();assert!((water_mass_fraction(&Material::free_base("Water",2.0),&c)-1.0).abs()<1e-12)}#[test]fn water_fraction_is_mass_weighted(){let c=default_catalog();let w=c.iter().find(|r|r.name=="Water").unwrap().properties.mass;let carbon=c.iter().find(|r|r.name=="Carbon").unwrap().properties.mass;let m=Material{composition:vec![crate::resources::MaterialComponent{resource:"Water".into(),amount:1.0},crate::resources::MaterialComponent{resource:"Carbon".into(),amount:1.0}],structure:None};assert!((water_mass_fraction(&m,&c)-w/(w+carbon)).abs()<1e-12)}#[test]fn water_fraction_zero_without_water(){let c=default_catalog();assert_eq!(water_mass_fraction(&Material::free_base("Carbon",2.0),&c),0.0)}#[test]fn pure_water_permeability_geometry_factor(){let c=default_catalog();let m=Material::free_base("Water",1.0);assert!((permeability(&m,&c,2.0,4.0).unwrap()-0.5).abs()<1e-12)}#[test]fn invalid_geometry_rejected(){let c=default_catalog();let m=Material::free_base("Water",1.0);assert!(permeability(&m,&c,-1.0,4.0).is_none());assert!(permeability(&m,&c,1.0,f64::NAN).is_none())}}
